      {
        synthetic: (notice) =>
          deps.inbox.admit({
            id: notice.id ?? report.notificationID,
            sessionID: notice.sessionID,
            item: {
              type: "synthetic",
              payload: SessionInbox.SyntheticPayload.make({
                text: notice.text,
                description: notice.description,
                metadata: notice.metadata,
              }),
              delivery: "steer",
            },
          }),
      },
      deps.jobs,
      report,
    ).pipe(
      Effect.as(true),
